data.code:
// One Code node replaces the retired lib.svg element builders. The gradient
// is defined first so the rect below can paint with fill="url(#card)".
return {
  output: [
    {
      name: "linearGradient",
      attributes: { id: "card", x1: "0%", y1: "0%", x2: "100%", y2: "100%" },
      children: [
        {
          name: "stop",
          attributes: { offset: "0%", style: "stop-color:#0ea5e9;stop-opacity:1" }
        },
        {
          name: "stop",
          attributes: { offset: "100%", style: "stop-color:#7c3aed;stop-opacity:1" }
        }
      ]
    },
    {
      name: "rect",
      attributes: { x: 0, y: 0, width: 400, height: 240, fill: "url(#card)" }
    }
  ]
};
